"""Captura nativa automática, menús y ejes iguales en primera persona."""
from pathlib import Path
import json
from playwright.sync_api import sync_playwright
from browser_server import local_server
ROOT=Path(__file__).resolve().parents[1];passed=[];errors=[]
def check(name,ok):
 assert ok,name
 passed.append(name);print('PASS',name,flush=True)
def locked(page):page.wait_for_function('FirstPerson.locked()&&FirstPerson.wasLocked')
def opened(page,state):page.wait_for_function("state=>Game.state===state&&!FirstPerson.locked()",arg=state)
with local_server(ROOT) as url,sync_playwright() as pw:
 browser=pw.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--enable-webgl','--enable-unsafe-swiftshader','--use-angle=swiftshader'])
 page=browser.new_page(viewport={'width':1440,'height':900});page.on('pageerror',lambda e:errors.append(str(e)))
 page.add_init_script("localStorage.setItem('riutex_pov_v016',JSON.stringify({enabled:true,sensitivityPercent:100}));addEventListener('load',()=>{SceneTransitions.enabled=false;SceneTransitions.finish();});")
 page.goto(url)
 check('El menú principal mantiene el cursor libre',page.evaluate("Game.state==='menu'&&!FirstPerson.locked()"))
 page.click('#bNew');locked(page)
 check('Nueva partida captura el ratón automáticamente desde el clic de inicio',page.evaluate("Game.state==='play'&&FirstPerson.armed&&document.pointerLockElement===Game.cv"))
 page.evaluate("Game.loop=()=>{};Hospital.toHospital(Game);Game.story.restrained=false;Hospital.inject(Game);Hospital.lobbyReached(Game);Game.story.seq='free';Game.state='play';UI.screen(null);Game.enemies=[];Game.carn=null;Game.keys={}")
 locked(page);resources=page.evaluate('JSON.stringify([Game.player.hp,Game.player.stamina,Game.player.energy,Game.player.weapon?.mag])')
 page.mouse.move(620,350);page.evaluate('Game.player.angle=0;FirstPerson.pitch=0');page.mouse.move(660,390,steps=4)
 native=page.evaluate('({yaw:Game.player.angle,pitch:FirstPerson.pitch})')
 check('Movimiento nativo equivalente tiene la misma sensibilidad X/Y',native['yaw']>0 and abs(native['yaw']-native['pitch'])<.00001)
 for code,state in [('k','tree'),('Tab','inv'),('m','map')]:
  page.keyboard.press(code);opened(page,state)
  check('Abrir '+state+' libera el ratón',page.evaluate('!FirstPerson.captureWanted&&!FirstPerson.locked()'))
  page.keyboard.press(code);locked(page)
  check('Cerrar '+state+' recupera la captura sin otro clic',page.evaluate("Game.state==='play'&&FirstPerson.locked()"))
 page.evaluate("Game.take(Game.items.find(i=>i.doc==='a1'))");opened(page,'doc')
 page.keyboard.press('j');locked(page)
 check('Cerrar un documento también vuelve a capturar automáticamente',page.evaluate("Game.state==='play'&&FirstPerson.locked()"))
 page.keyboard.press('Tab');opened(page,'inv');page.keyboard.press('Escape');locked(page)
 check('Escape desde inventario vuelve al juego y recupera el ratón',page.evaluate("Game.state==='play'&&FirstPerson.locked()"))
 page.keyboard.press('Escape');opened(page,'pause');page.wait_for_timeout(260)
 page.evaluate('for(let i=0;i<30;i++)FirstPerson.tick(1/60,Game)')
 check('Escape de juego pausa y no intenta volver a encerrar el cursor',page.evaluate("Game.state==='pause'&&!FirstPerson.locked()&&!FirstPerson.captureWanted"))
 page.click('#bRes');locked(page)
 check('Reanudar desde pausa recupera el bloqueo con el botón de reanudar',page.evaluate("Game.state==='play'&&FirstPerson.locked()"))
 page.evaluate('document.exitPointerLock()');opened(page,'pause');page.wait_for_timeout(260)
 check('Una salida de captura del navegador también pausa sin reintentos',page.evaluate("!FirstPerson.locked()&&!FirstPerson.captureWanted"))
 page.evaluate("window.nativeCapture=Game.cv.requestPointerLock;window.captureAttempts=0;Game.cv.requestPointerLock=()=>{captureAttempts++;throw Error('denied for test')};void 0")
 page.click('#bRes');page.evaluate('for(let i=0;i<60;i++)FirstPerson.tick(1/60,Game)')
 check('Un rechazo conserva respaldo y solicita una sola vez por retorno',page.evaluate("Game.state==='play'&&FirstPerson.fallback&&FirstPerson.armed&&captureAttempts===1&&!FirstPerson.capturePending"))
 page.mouse.move(620,350);page.evaluate('Game.player.angle=0;FirstPerson.pitch=0');page.mouse.down(button='right');page.mouse.move(660,390,steps=4);page.mouse.up(button='right')
 fallback=page.evaluate('({yaw:Game.player.angle,pitch:FirstPerson.pitch})')
 check('El arrastre alternativo también usa la misma ganancia X/Y',fallback['yaw']>0 and abs(fallback['yaw']-fallback['pitch'])<.00001)
 page.click('#povCaptureButton')
 check('El botón queda disponible para reintentar cuando el navegador exige interacción',page.evaluate('captureAttempts===2&&FirstPerson.fallback&&!Game.mouse.down&&!Game.mouse.clicked&&!Game.mouse.rclick'))
 page.evaluate('Game.cv.requestPointerLock=window.nativeCapture;void 0')
 page.click('#povCaptureButton');locked(page)
 check('Recuperar la API permite volver a captura nativa',page.evaluate('document.pointerLockElement===Game.cv'))
 page.keyboard.press('k');opened(page,'tree')
 page.evaluate("window.recoveryCapture=Game.cv.requestPointerLock;window.recoveryRequests=0;Game.cv.requestPointerLock=()=>{recoveryRequests++;if(recoveryRequests===1)return Promise.reject(Error('gesture required'));return recoveryCapture.call(Game.cv);};void 0")
 page.keyboard.press('k');page.wait_for_function('FirstPerson.fallback&&!FirstPerson.capturePending')
 check('Un rechazo asíncrono deja pendiente la recuperación por interacción',page.evaluate('recoveryRequests===1&&!FirstPerson.locked()&&Game.state===\'play\''))
 page.keyboard.press('w');locked(page)
 check('Moverse recupera el ratón automáticamente sin pulsar Bloquear ratón',page.evaluate('recoveryRequests===2&&document.pointerLockElement===Game.cv'))
 page.evaluate('Game.cv.requestPointerLock=window.recoveryCapture;window.dispatchEvent(new Event(\'blur\'));void 0')
 page.wait_for_function('!FirstPerson.locked()&&!FirstPerson.ignoreUnlock')
 page.evaluate('window.dispatchEvent(new Event(\'focus\'));void 0')
 check('Perder el foco mantiene la pausa y el cursor libre hasta reanudar',page.evaluate("Game.state==='pause'&&!FirstPerson.locked()"))
 page.click('#bRes');locked(page)
 check('Reanudar tras volver a la ventana recupera el ratón sin otro botón',page.evaluate("Game.state==='play'&&FirstPerson.captureWanted&&FirstPerson.locked()"))
 check('Cambiar ventanas y capturar no dispara ni consume recursos',resources==page.evaluate('JSON.stringify([Game.player.hp,Game.player.stamina,Game.player.energy,Game.player.weapon?.mag])'))
 page.keyboard.press('Escape');opened(page,'pause');page.wait_for_timeout(260)
 page.locator('#pauseFirstPerson').uncheck();page.click('#bRes')
 check('Topdown mantiene el cursor libre al reanudar',page.evaluate("!FirstPerson.enabled&&!FirstPerson.locked()&&!FirstPerson.captureWanted&&Game.state==='play'"))
 page.evaluate('Game.toMenu()');page.click('#bMenuOptions');page.locator('#menuFirstPerson').check();page.click('#bMenuOptionsClose')
 page.evaluate('SceneTransitions.enabled=true');page.click('#bNew');page.wait_for_function('!SceneTransitions.active&&FirstPerson.locked()')
 check('Un fundido real termina con captura automática y sin clic extra',page.evaluate("Game.state==='play'&&FirstPerson.locked()"))
 check('Sin errores JavaScript',not errors)
 (ROOT/'artifacts/pov-controls-v020-browser-results.json').write_text(json.dumps({'version':json.loads((ROOT/'package.json').read_text())['version'],'passed':passed,'errors':errors,'native_look':native,'fallback_look':fallback,'scope':'Pointer Lock nativo de Chromium, clic de inicio, retorno por K/Tab/M/J/Escape, pausa, salida de captura, denegación preparada y fundido real. No elude permisos del navegador.'},ensure_ascii=False,indent=2)+'\n')
 browser.close()
